import subprocess, json, time, sys, os, threading

class Client:
    def __init__(self, args, cwd="/workspace"):
        self.proc=subprocess.Popen(['./executable']+args, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd)
        self.buf=b''
        self.stderr_lines=[]
        def read_stderr():
            for line in self.proc.stderr:
                self.stderr_lines.append(line)
                print("STDERR:", line.decode(errors='replace'), end='', flush=True)
        threading.Thread(target=read_stderr, daemon=True).start()
    def send(self,obj):
        data=json.dumps(obj).encode()
        print(">>",obj)
        self.proc.stdin.write(b"Content-Length: %d\r\n\r\n"%len(data)+data)
        self.proc.stdin.flush()
    def recv(self, timeout=10):
        # read one message
        import select
        end=time.time()+timeout
        # need header
        while b'\r\n\r\n' not in self.buf:
            if time.time()>end: raise TimeoutError(f"header timeout buf={self.buf!r} poll={self.proc.poll()}")
            r,_,_=select.select([self.proc.stdout],[],[],0.5)
            if r:
                chunk=os.read(self.proc.stdout.fileno(),4096)
                if not chunk: raise EOFError(f"eof buf={self.buf}")
                self.buf+=chunk
        hdr,rest=self.buf.split(b'\r\n\r\n',1)
        length=None
        headers={}
        for line in hdr.split(b'\r\n'):
            k,v=line.split(b':',1); headers[k.strip().lower()]=v.strip()
        length=int(headers[b'content-length'])
        while len(rest)<length:
            if time.time()>end: raise TimeoutError("body timeout")
            r,_,_=select.select([self.proc.stdout],[],[],0.5)
            if r:
                chunk=os.read(self.proc.stdout.fileno(),4096)
                if not chunk: raise EOFError()
                rest+=chunk
        body=rest[:length]
        self.buf=rest[length:]
        obj=json.loads(body)
        print("<<",obj)
        return obj
    def expect(self, timeout=10):
        try:
            return self.recv(timeout)
        except Exception as e:
            print("recv err",e)
            return None

if __name__=="__main__":
    c=Client(['--stdio'])
    c.send({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"processId":1234,"rootUri":"file:///tmp","capabilities":{},"workspaceFolders":[{"uri":"file:///tmp","name":"tmp"}]}})
    for i in range(10):
        m=c.expect(timeout=6)
        if m is None: break
        if m.get('id')==1: break
    c.send({"jsonrpc":"2.0","method":"initialized","params":{}})
    for i in range(10):
        m=c.expect(timeout=6)
        if m is None: break
    c.send({"jsonrpc":"2.0","id":2,"method":"shutdown","params":None})
    for i in range(5):
        m=c.expect(timeout=3)
        if m and m.get('id')==2: break
    c.send({"jsonrpc":"2.0","method":"exit"})
    try:
        print("wait",c.proc.wait(timeout=3))
    except Exception as e:
        print(e); c.proc.kill()
PY
