import subprocess, os, pathlib, shutil
home=pathlib.Path.home()
sysroot=home/".rustowl/sysroot/nightly-2025-06-20-x86_64-unknown-linux-gnu"
def run(args, env=None):
    e=os.environ.copy()
    if env: e.update(env)
    p=subprocess.run(['./executable']+args, capture_output=True, timeout=6, env=e, text=True)
    print(args, "env", env, "rc", p.returncode)
    print(p.stderr)
    print(p.stdout)
    print("---")

# test various fake sysroot setups
for setup in ["none","empty_dir","bin_cargo","bin_rustowlc","both","lib"]:
    if sysroot.exists(): shutil.rmtree(sysroot)
    if setup=="empty_dir": sysroot.mkdir(parents=True)
    elif setup=="bin_cargo":
        (sysroot/"bin").mkdir(parents=True); (sysroot/"bin/cargo").write_text("#!/bin/sh\necho fake cargo\n"); os.chmod(sysroot/"bin/cargo",0o755)
    elif setup=="bin_rustowlc":
        (sysroot/"bin").mkdir(parents=True); (sysroot/"bin/rustowlc").write_text("x")
    elif setup=="both":
        (sysroot/"bin").mkdir(parents=True)
        for n in ["cargo","rustowlc","rustc"]:
            pth=sysroot/f"bin/{n}"; pth.write_text("#!/bin/sh\necho fake\n"); os.chmod(pth,0o755)
    elif setup=="lib":
        (sysroot/"lib/rustlib/x86_64-unknown-linux-gnu/lib").mkdir(parents=True)
    print("SETUP",setup)
    run(['check','/tmp'])
PY"}

