def jaro(s1,s2):
    if s1==s2: return 1.0
    l1,l2=len(s1),len(s2)
    md=max(l1,l2)//2-1
    md=max(md,0)
    m1=[False]*l1; m2=[False]*l2; matches=0
    for i,ch in enumerate(s1):
        for j in range(max(0,i-md), min(i+md+1,l2)):
            if not m2[j] and s2[j]==ch:
                m1[i]=True; m2[j]=True; matches+=1; break
    if not matches: return 0.0
    t=0; k=0
    for i in range(l1):
        if not m1[i]: continue
        while not m2[k]: k+=1
        if s1[i]!=s2[k]: t+=1
        k+=1
    t//=2
    return (matches/l1+matches/l2+(matches-t)/matches)/3
def jw(a,b):
    j=jaro(a,b); p=0
    for x,y in zip(a,b):
        if x==y and p<4: p+=1
        else: break
    return j+p*0.1*(1-j)
for cand in ['cle','che','inst','instal','uninstal']:
    targets=['check','clean','toolchain','completions','help','install','uninstall']
    print(cand, [(t,round(jaro(cand,t),3),round(jw(cand,t),3)) for t in targets])
