        return None
    low = text.lower()
    # Rust log crate LevelFilter::from_str is case-insensitive but does not trim.
    if low in LOG_LEVELS and text == text.strip() and "_" not in text:
        # The exact names recognised are off/error/warn/info/debug/trace.
        # Case-insensitivity is handled by low above; strings such as
        # "warning" are not valid and fall through to the default.
        return LOG_LEVELS[low]
    return None

def init_logger(default_level_name):
    global _log_level_value
    default = LOG_LEVELS[default_level_name]
    env = os.environ.get("RUST_LOG")
    if env is not None:
        parsed = _parse_log_level(env)
        _log_level_value = parsed if parsed is not None else default
    else:
        _log_level_value = default

def log_msg(level_name, target, message):
