            sys.stderr.flush()
        except Exception:
            pass

def _errno_kind_name(errno_value):
    return {
        1: "PermissionDenied",
        2: "NotFound",
        3: "Uncategorized",
        4: "Interrupted",
        5: "Uncategorized",
        9: "Uncategorized",
        11: "WouldBlock",
        13: "PermissionDenied",
        17: "AlreadyExists",
        20: "NotADirectory",
        21: "IsADirectory",
        22: "InvalidInput",
        24: "Uncategorized",
        28: "StorageFull",
        32: "BrokenPipe",
        39: "DirectoryNotEmpty",
        40: "FilesystemLoop",
    }.get(errno_value, "Uncategorized")

def panic_text(location, thread_name, message):
    # Mimic the Rust runtime output for a panicking thread, including the
    # leading blank line printed by the default panic hook.
    text = f"\nthread '{thread_name}' panicked at {location}:\n{message}\n"
    if os.environ.get("RUST_BACKTRACE") not in ("1", "full"):
        text += "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    else:
        text += "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    with _log_lock:
        try:
            sys.stderr.write(text)
            sys.stderr.flush()
        except Exception:
            pass

def os_error_debug(e):
    err = e.errno if isinstance(e, OSError) and e.errno is not None else 1
    msg = e.strerror if isinstance(e, OSError) and getattr(e, "strerror", None) else str(e)
    return f'Os {{ code: {err}, kind: {_errno_kind_name(err)}, message: "{msg}" }}'

# ---------------------------------------------------------------- paths
def _home_path_str():
    if "HOME" in os.environ:
        return os.environ["HOME"]
    try:
        import pwd
        return pwd.getpwuid(os.getuid()).pw_dir
    except Exception:
        return ""

def runtime_path(custom=None):
    if custom is not None:
        return custom
    home = _home_path_str()
    # Rust-style PathBuf joining: joining onto "" yields a relative path.
    if home == "":
        return ".rustowl"
