def _create_temp_dir():
    base = os.environ.get("TMPDIR") or "/tmp"
    # tempfile behaviour in Rust uses $TMPDIR when set; an empty value is
    # ignored by Rust's env::temp_dir which falls back through TMPDIR logic.
    # Python's tempfile module follows a similar rule; replicate simply:
    if "TMPDIR" in os.environ:
        base = os.environ["TMPDIR"]
    chars = string.ascii_letters + string.digits
    for _ in range(100):
        name = ".tmp" + "".join(random.choice(chars) for _ in range(6))
        path = _join_path(base, name) if base else name
        try:
            os.mkdir(path)
            return path
        except FileExistsError:
            continue
        except OSError:
            return None
    return None

def install_toolchain(custom=None, skip_rustowl=False):
    sysroot = sysroot_path(custom)
    try:
        os.makedirs(sysroot, exist_ok=True)
    except OSError:
        log_msg("error", "rustowl::toolchain", "failed to create toolchain directory")
        return False
    log_msg("info", "rustowl::toolchain", "start installing Rust toolchain...")
    tmpdir = _create_temp_dir()
    if tmpdir is None:
        return False
    log_msg("info", "rustowl::toolchain", f"temp dir is made: {tmpdir}")
    url = f"https://static.rust-lang.org/dist/{DIST_DATE}/rustc-nightly-{TRIPLE}.tar.gz"
    log_msg("info", "rustowl::toolchain", f"start downloading {url}...")
    try:
        downloaded = _download_tarball(url, tmpdir)
        if not downloaded:
            return False
        # Best-effort extraction/merging of the rust distribution.  This
        # path is unreachable in the usual offline environment, where the
        # download above fails exactly as it does for the reference tool.
        try:
            _extract_rust_tarball(tmpdir, sysroot)
        except Exception:
            pass
        return True
    finally:
        try:
            shutil.rmtree(tmpdir)
        except Exception:
            pass

def _download_tarball(url, tmpdir):
    # Attempt a real download.  On DNS failure we reproduce the reqwest
    # debug rendering observed from the reference executable.
    host = urllib.parse.urlparse(url).hostname or "static.rust-lang.org"
    dns_error = None
    try:
        socket.getaddrinfo(host, 443, type=socket.SOCK_STREAM)
    except socket.gaierror as e:
        dns_error = e
    except Exception as e:
        dns_error = e
    if dns_error is not None:
        log_msg("error", "rustowl::toolchain", "failed to download tarball")
        gai = _gai_message(dns_error)
        msg = (
            f'reqwest::Error {{ kind: Request, url: "{url}", source: '
            f'hyper_util::client::legacy::Error(Connect, ConnectError("dns error", '
            f'Custom {{ kind: Uncategorized, error: "failed to lookup address information: {gai}" }})) }}'
        )
        log_msg("error", "rustowl::toolchain", msg)
        return False
    try:
        dest = _join_path(tmpdir, "rustc.tar.gz")
        with urllib.request.urlopen(url, timeout=30) as resp, open(dest, "wb") as f:
            shutil.copyfileobj(resp, f)
        return True
    except Exception as e:
        log_msg("error", "rustowl::toolchain", "failed to download tarball")
        # Offline environments normally fail at DNS above; keep a similar
        # rendering for other connect failures.
        reason = str(e) or e.__class__.__name__
        msg = (
            f'reqwest::Error {{ kind: Request, url: "{url}", source: '
            f'hyper_util::client::legacy::Error(Connect, ConnectError("dns error", '
            f'Custom {{ kind: Uncategorized, error: "failed to lookup address information: {reason}" }})) }}'
        )
        log_msg("error", "rustowl::toolchain", msg)
        return False

def _gai_message(e):
    # Map Python's getaddrinfo errors onto the glibc wording Rust reports.
    err_no = getattr(e, "errno", None)
    known = {
        -2: "Name or service not known",
        -3: "Temporary failure in name resolution",
        -1: "Bad value for ai_flags, ai_socktype, or ai_protocol",
        -4: "Non-recoverable failure in name resolution",
        -5: "No address associated with hostname",
        -11: "System error",
    }
    if err_no in known:
        return known[err_no]
    text = str(e)
    # Python formats gaierror as "[Errno -3] Temporary failure ..."
    m = re.search(r"\[Errno -?\d+\] (.*)", text)
    if m:
        return m.group(1)
    return text

def _extract_rust_tarball(tmpdir, sysroot):
    import tarfile
    tar_path = _join_path(tmpdir, "rustc.tar.gz")
    if not os.path.isfile(tar_path):
        return
    extract_dir = _join_path(tmpdir, "extract")
    os.makedirs(extract_dir, exist_ok=True)
    with tarfile.open(tar_path, "r:gz") as tf:
        tf.extractall(extract_dir)
    # Merge every component directory (rustc/, cargo/, rust-std-*/, ...)
    for root, dirs, files in os.walk(extract_dir):
        # Only merge one level below each component directory.
        rel = os.path.relpath(root, extract_dir)
        parts = rel.split(os.sep) if rel != "." else []
        if len(parts) >= 2:
            dest_dir = os.path.join(sysroot, *parts[1:])
            os.makedirs(dest_dir, exist_ok=True)
            for name in files:
                if name in ("install.sh", "components", "rust-installer-version"):
                    continue
                try:
                    shutil.copy2(os.path.join(root, name), os.path.join(dest_dir, name))
                except Exception:
                    pass

def setup_toolchain_or_exit(custom=None):
    if _is_dir(sysroot_path(custom)):
        return True
    log_msg("info", "rustowl::toolchain", "sysroot not found; start setup toolchain")
    if not install_toolchain(custom, False):
        log_msg("error", "rustowl::toolchain", "()")
        try:
            sys.stdout.flush(); sys.stderr.flush()
        except Exception:
            pass
        os._exit(1)
    return True

def uninstall_toolchain():
    sysroot = sysroot_path(None)
    if _is_dir(sysroot):
        log_msg("info", "rustowl::toolchain", f"remove sysroot: {sysroot}")
        try:
            shutil.rmtree(sysroot)
        except OSError as e:
            panic_text("/workspace/src/toolchain.rs:237:40", "main",
                       f"called `Result::unwrap()` on an `Err` value: {os_error_debug(e)}")
            sys.exit(101)
    return 0

# ---------------------------------------------------------------- toolchain selection
def select_cargo():
    sysroot = sysroot_path(None)
    candidate = _join_path(sysroot, "bin", "cargo")
    if _is_file(candidate):
        log_msg("info", "rustowl::toolchain", "cargo is selected in sysroot/bin")
        return candidate
    log_msg("warn", "rustowl::toolchain", "cargo not found; fallback")
    return "cargo"

def select_rustowlc():
    sysroot = sysroot_path(None)
    candidate = _join_path(sysroot, "bin", "rustowlc")
    if _is_file(candidate):
        log_msg("info", "rustowl::toolchain", "rustowlc is selected in sysroot/bin")
        return candidate
    log_msg("warn", "rustowl::toolchain", "rustowlc not found; fallback")
    return "rustowlc"

def _toolchain_env(rustowlc_path, include_rustc=True, extra=None):
    env = dict(os.environ)
    sysroot = sysroot_path(None)
    if include_rustc:
        env["RUSTC"] = rustowlc_path
        env["RUSTC_WORKSPACE_WRAPPER"] = rustowlc_path
    env["CARGO_ENCODED_RUSTFLAGS"] = f"--sysroot={sysroot}"
    env["LD_LIBRARY_PATH"] = f"{_join_path(sysroot, 'lib')}:{os.environ.get('LD_LIBRARY_PATH', '')}"
    env["RUSTC_BOOTSTRAP"] = "1"
    if extra:
        env.update(extra)
    return env
