# ---------------------------------------------------------------- URL handling
class UrlInfo:
    __slots__ = ("raw", "scheme", "host", "path", "cannot_be_base")
    def __init__(self, raw, scheme, host, path, cannot_be_base=False):
        self.raw = raw
        self.scheme = scheme
        self.host = host
        self.path = path
        self.cannot_be_base = cannot_be_base

_URL_SCHEME_RE = re.compile(r"^([A-Za-z][A-Za-z0-9+.-]*):(.*)$", re.DOTALL)

def parse_url(value):
    """Return (UrlInfo, error_message).  error_message is the serde style
    message produced when Url deserialisation fails."""
    if not isinstance(value, str):
        return None, f"invalid type: {_serde_type_desc(value)}, expected a string representing an URL"
    m = _URL_SCHEME_RE.match(value)
    if not m:
        return None, f'relative URL without a base: "{value}"'
    scheme = m.group(1).lower()
    rest = m.group(2)
    host = ""
    path = rest
    cannot = False
    # Strip query/fragment for path processing (they remain part of a URL
    # but do not affect the file path).
    # First detect authority for schemes using //.
    if rest.startswith("//"):
        after = rest[2:]
        # authority ends at /, ? or #
        idx = len(after)
        for ch in "/?#":
            p = after.find(ch)
            if p != -1:
                idx = min(idx, p)
        authority = after[:idx]
        tail = after[idx:]
        if "@" in authority:
            authority = authority.rsplit("@", 1)[1]
        if authority.startswith("["):
            end = authority.find("]")
            host = authority[1:end].lower() if end != -1 else authority.lower()
            port_part = authority[end+1:] if end != -1 else ""
            if port_part.startswith(":") and port_part[1:] != "":
                if not port_part[1:].isdigit():
                    return None, "invalid port number"
        else:
            if ":" in authority:
                h, p = authority.rsplit(":", 1)
                if p != "" and not p.isdigit():
                    return None, "invalid port number"
                host = h.lower()
            else:
                host = authority.lower()
        path = tail
    else:
        if scheme in ("file", "http", "https", "ws", "wss", "ftp"):
            # Special schemes are parsed as if // were present in many
            # shorthand forms (file:/tmp works like file:///tmp).
            if scheme == "file":
                # Cannot-be-a-base file URLs (file:relative) keep their
                # opaque path in the Rust url crate.
                if not rest.startswith("/"):
                    cannot = True
                path = rest
            else:
                path = rest
        else:
            cannot = not rest.startswith("/")
            path = rest
    # Remove query/fragment from path.
    for ch in ("?", "#"):
        p = path.find(ch)
        if p != -1:
            path = path[:p]
