def _rust_parent(path):
    # Rust Path::parent for a POSIX path string.
    if path == "":
        return ""
    stripped = path
    while len(stripped) > 1 and stripped.endswith("/"):
        stripped = stripped[:-1]
    if stripped == "/":
        return None  # parent of root
    idx = stripped.rfind("/")
    if idx == -1:
        return ""
    if idx == 0:
        return "/"
    return stripped[:idx]

def _rust_extension(path):
    name = path.rsplit("/", 1)[-1]
    if name == "":
        return None
    # Rust Path::extension logic
    if name.startswith(".") and name.count(".") == 1:
        return None
    if "." not in name:
        return None
    return name.rsplit(".", 1)[1]

