class PendingRequest:
    __slots__ = ("request_id", "cancelled", "responded", "thread")
    def __init__(self, request_id):
        self.request_id = request_id
        self.cancelled = False
        self.responded = False
        self.thread = None

class LspServer:
    def __init__(self, instream, outstream):
        self.instream = instream
        self.outstream = outstream
        self.out_lock = threading.Lock()
        self.backend = Backend()
        self.state = "uninitialized"  # uninitialized|initialized|shutdown|exited
        self.state_lock = threading.Lock()
        self.pending = {}
        self.pending_lock = threading.Lock()
        self.request_threads = []

    # ---- output
    def send_obj(self, obj):
        body = dumps_compact(obj).encode("utf-8", errors="surrogateescape")
        frame = b"Content-Length: %d\r\n\r\n" % len(body) + body
        with self.out_lock:
            try:
                self.outstream.write(frame)
                self.outstream.flush()
            except Exception:
                pass

    def send_result(self, request_id, result):
        self.send_obj({"jsonrpc": "2.0", "result": result, "id": request_id})

    def send_error(self, request_id, code, message, data_present=False, data=None):
        err = {"code": code, "message": message}
        if data_present:
            err["data"] = data
        self.send_obj({"jsonrpc": "2.0", "error": err, "id": request_id})

    def respond_pending(self, pending, obj):
        with self.pending_lock:
            if pending.responded:
                return False
            pending.responded = True
            self.pending.pop(_id_key(pending.request_id), None)
        self.send_obj(obj)
        return True

    def result_for_pending(self, pending, result):
        self.respond_pending(pending, {"jsonrpc": "2.0", "result": result, "id": pending.request_id})

    def error_for_pending(self, pending, code, message, data_present=False, data=None):
        err = {"code": code, "message": message}
        if data_present:
            err["data"] = data
        self.respond_pending(pending, {"jsonrpc": "2.0", "error": err, "id": pending.request_id})

    def cancel_pending_by_id(self, request_id):
        key = _id_key(request_id)
        with self.pending_lock:
            pending = self.pending.get(key)
            if pending is None or pending.responded:
                return False
            pending.cancelled = True
            pending.responded = True
            self.pending.pop(key, None)
        self.send_obj({"jsonrpc": "2.0", "error": {"code": -32800, "message": "Canceled"}, "id": pending.request_id})
        return True

    def cancel_all_pending(self):
        with self.pending_lock:
            pendings = list(self.pending.values())
            for p in pendings:
                p.cancelled = True
                p.responded = True
            self.pending.clear()
        for p in pendings:
            self.send_obj({"jsonrpc": "2.0", "error": {"code": -32800, "message": "Canceled"}, "id": p.request_id})

