                    self.send_error(None, -32700, "Parse error")
                return _EOF, False
            saw_any = True
            if line in (b"\r\n", b"\n"):
                break
            # A header line must contain a colon.
            if b":" not in line:
                header_error = True
                continue
            name, _, value = line.partition(b":")
            try:
                hname = name.decode("ascii", errors="strict")
                hval = value.strip().decode("ascii", errors="replace")
            except Exception:
                header_error = True
                continue
            headers[hname] = hval
        if header_error or "Content-Length" not in headers:
            self.send_error(None, -32700, "Parse error")
            return _PARSE_CONTINUE, True
        raw_len = headers["Content-Length"].strip()
        try:
            length = int(raw_len)
            if length < 0 or str(length) != raw_len.strip() and not raw_len.strip().lstrip("0").isdigit():
                # int() is already strict enough for "abc"; keep the
                # explicit check for symmetry with the Rust codec.
                pass
        except Exception:
            self.send_error(None, -32700, "Parse error")
            return _PARSE_CONTINUE, True
        if length < 0:
            self.send_error(None, -32700, "Parse error")
            return _PARSE_CONTINUE, True
        if length == 0:
            return _PARSE_CONTINUE, False
        body = b""
        while len(body) < length:
            chunk = self.instream.read(length - len(body))
            if not chunk:
                if body:
                    self.send_error(None, -32700, "Parse error")
                return _EOF, False
            body += chunk
        try:
            text = body.decode("utf-8")
            obj = json.loads(text, parse_float=JsonFloat, parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))
        except Exception:
            self.send_error(None, -32700, "Parse error")
            return _PARSE_CONTINUE, True
        return obj, False

    # ---- message processing (called on the reader thread)
    def _process_message(self, obj):
        # Responses from the client are dropped.
        if isinstance(obj, dict) and "method" not in obj and ("result" in obj or "error" in obj):
            return
        if not isinstance(obj, dict) or obj.get("jsonrpc") != "2.0":
            self.send_error(None, -32600, "Invalid request")
            return
        method_present = "method" in obj
        method = obj.get("method", "")
        if method_present and not isinstance(method, str):
            self.send_error(None, -32600, "Invalid request")
            return
        is_request = "id" in obj
        request_id = obj.get("id")
        if is_request and not _is_valid_id(request_id):
            self.send_error(None, -32600, "Invalid request")
            return
        params_marker = obj["params"] if "params" in obj else _MISSING

        if not is_request:
            self._process_notification(method, params_marker)
            return

        # Requests -------------------------------------------------
        # exit is handled as a notification by tower-lsp even when the
        # peer (incorrectly) supplies an id.
        if method == "exit":
            self._handle_exit()
            return
        state = self.get_state()
        if state == "exited":
            return
        if method in ("$/setTrace", "$/progress") or (method.startswith("$/") and method != "$/cancelRequest"):
            return
        if method == "$/cancelRequest":
            self.send_error(request_id, -32600, "Invalid request")
            return
        known = (method in REQUEST_METHODS_MISSING or method in NOTIFICATION_METHODS
                 or method in ("initialize", "shutdown", "rustowl/cursor", "rustowl/analyze"))
        if not known:
            self.send_error(request_id, -32601, "Method not found", True, method)
            return
        if method in NOTIFICATION_METHODS:
            if state == "uninitialized":
                self.send_error(request_id, -32002, "Server not initialized")
            else:
                self.send_error(request_id, -32600, "Invalid request")
            return
        if state == "uninitialized":
            if method != "initialize":
                self.send_error(request_id, -32002, "Server not initialized")
                return
            self._spawn_request(request_id, method, params_marker)
            return
        if state == "shutdown":
            self.send_error(request_id, -32600, "Invalid request")
            return
        # state == initialized
        if method == "initialize":
            self.send_error(request_id, -32600, "Invalid request")
            return
        if method == "shutdown":
            self.set_state("shutdown")
            if params_marker is _MISSING:
                self.send_result(request_id, None)
            else:
                self.send_error(request_id, -32602, f"Unexpected params: {dumps_compact(params_marker)}")
            return
        self._spawn_request(request_id, method, params_marker)

    def _spawn_request(self, request_id, method, params_marker):
        pending = PendingRequest(request_id)
        with self.pending_lock:
            self.pending[_id_key(request_id)] = pending
        def run():
            try:
                self._execute_request(pending, method, params_marker)
            except JsonRpcError as e:
                self.error_for_pending(pending, e.code, e.message, e.data_present, e.data)
            except Exception:
                # Internal handlers are written not to raise, but keep
                # the transport alive should one do so.
                self.error_for_pending(pending, -32603, "Internal error")
        t = threading.Thread(target=run, daemon=True)
        pending.thread = t
        self.request_threads.append(t)
        t.start()

    def _execute_request(self, pending, method, params_marker):
        if method == "initialize":
            result = self._do_initialize(params_marker, pending)
            if result is _CANCELLED:
                return
            self.result_for_pending(pending, result)
            return
        if method == "rustowl/cursor":
            position, doc_uri = validate_cursor_params(params_marker)
            result = self._do_cursor(position, doc_uri)
            self.result_for_pending(pending, result)
            return
        if method == "rustowl/analyze":
            # Validate AnalyzeRequest (an empty struct).
            if params_marker is _MISSING:
                raise JsonRpcError(-32602, "Missing params field")
            p = params_marker
            if isinstance(p, dict):
                pass
            elif isinstance(p, (list, tuple)):
                if len(p) != 0:
                    raise JsonRpcError(-32602, f"invalid length {len(p)}, expected fewer elements in array")
            else:
                raise JsonRpcError(-32602, f"invalid type: {_serde_type_desc(p)}, expected struct AnalyzeRequest")
            log_msg("info", "rustowl::lsp::backend", "rustowl/analyze request received")
            self.backend.trigger_analysis(binary_crate=True)
            self.result_for_pending(pending, {})
            return
        # Generic, unimplemented request methods.
        if params_marker is _MISSING:
            raise JsonRpcError(-32602, "Missing params field")
        err = validate_generic_params(method, params_marker)
        if err:
            raise JsonRpcError(-32602, err)
        raise JsonRpcError(-32601, "Method not found")

    def _do_initialize(self, params_marker, pending):
        params = validate_initialize_params(params_marker)
        targets = []
        root_uri = params.get("rootUri") if isinstance(params, dict) else None
        if isinstance(root_uri, str):
            info, _ = parse_url(root_uri)
            path = url_to_file_path(info)
            if path is not None:
                tgt = get_target(path)
                if tgt is not None:
                    targets.append(tgt)
        folders = params.get("workspaceFolders") if isinstance(params, dict) else None
        if isinstance(folders, (list, tuple)):
            for folder in folders:
                uri = None
                if isinstance(folder, dict):
                    uri = folder.get("uri")
                elif isinstance(folder, (list, tuple)) and folder:
                    uri = folder[0]
                if isinstance(uri, str):
                    info, _ = parse_url(uri)
                    path = url_to_file_path(info)
                    if path is not None:
                        tgt = get_target(path)
                        if tgt is not None:
                            targets.append(tgt)
        for tgt in targets:
            self.backend.add_target(tgt)
        if pending.cancelled:
            return _CANCELLED
        # Only now is the session considered initialised, matching the
        # moment tower-lsp records the initialize call as complete.
        self.set_state("initialized")
        self.backend.trigger_analysis(binary_crate=False)
        return CAPABILITIES_RESULT

    def _do_cursor(self, position, doc_uri):
        path = None
        info = None
        if isinstance(doc_uri, str):
            info, _ = parse_url(doc_uri)
            converted = url_to_file_path(info)
            if converted is not None and _is_file(converted):
                path = converted
        is_analyzed = False
        decorations = []
        if path is not None:
            with self.backend.lock:
                if path in self.backend.analyzed:
                    is_analyzed = True
                    decorations = list(self.backend.analyzed.get(path, []))
        with self.backend.lock:
            status = self.backend.status
        if status == "analyzing":
            out_status = "analyzing"
        elif is_analyzed:
            out_status = "analyzed"
        else:
            out_status = "error"
        return {"decorations": decorations, "is_analyzed": is_analyzed, "path": path, "status": out_status}

    # ---- notifications
    def _process_notification(self, method, params_marker):
        if method == "exit":
            self._handle_exit()
            return
        state = self.get_state()
        if state == "exited":
            return
        if method == "$/cancelRequest":
            self._handle_cancel(params_marker)
            return
        if method.startswith("$/"):
            return
        if state != "initialized":
            return
        if method == "textDocument/didOpen":
            t = threading.Thread(target=self._handle_did_open, args=(params_marker,), daemon=True)
            t.start()
        elif method == "workspace/didChangeWorkspaceFolders":
            t = threading.Thread(target=self._handle_workspace_folders, args=(params_marker,), daemon=True)
            t.start()
        else:
            return

    def _handle_exit(self):
        if self.get_state() == "exited":
            return
        self.set_state("exited")
        self.cancel_all_pending()

    def _handle_cancel(self, params_marker):
        request_id = _MISSING
        if isinstance(params_marker, dict):
            request_id = params_marker.get("id", _MISSING)
        elif isinstance(params_marker, (list, tuple)) and params_marker:
            request_id = params_marker[0]
        if request_id is _MISSING or not _is_valid_id(request_id):
            return
        self.cancel_pending_by_id(request_id)

    def _handle_did_open(self, params_marker):
        if not isinstance(params_marker, dict):
            return
        doc = params_marker.get("textDocument")
        if not isinstance(doc, dict):
            return
        if doc.get("languageId") != "rust":
            return
        uri = doc.get("uri")
        if not isinstance(uri, str):
            return
        info, _ = parse_url(uri)
        path = url_to_file_path(info)
        if path is None:
            return
        if not _is_file(path):
            return
        target = get_target(path)
        if target is None:
            return
        self.backend.add_target(target)
        self.backend.trigger_analysis(binary_crate=False)

    def _handle_workspace_folders(self, params_marker):
        if not isinstance(params_marker, dict):
            return
        event = params_marker.get("event")
        if not isinstance(event, dict):
            return
        added = event.get("added")
        if not isinstance(added, (list, tuple)):
            return
        for folder in added:
            uri = None
            if isinstance(folder, dict):
                uri = folder.get("uri")
            elif isinstance(folder, (list, tuple)) and folder:
                uri = folder[0]
            if not isinstance(uri, str):
                continue
            info, _ = parse_url(uri)
            path = url_to_file_path(info)
            if path is None:
                continue
            target = get_target(path)
            if target is None:
                continue
            self.backend.add_target(target)
            self.backend.trigger_analysis(binary_crate=False)

class _Eof:
    pass
_EOF = _Eof()
class _ParseContinue:
    pass
_PARSE_CONTINUE = _ParseContinue()
class _Cancelled:
    pass
_CANCELLED = _Cancelled()

def run_lsp_server():
    # Banner is not produced through the logging framework: it appears
    # even when RUST_LOG=off.
    try:
        sys.stderr.write(f"RustOwl v{VERSION}\n")
        sys.stderr.write("This is an LSP server. You can use --help flag to show help.\n")
        sys.stderr.flush()
    except Exception:
        pass
    init_logger("warn")
    server = LspServer(sys.stdin.buffer, sys.stdout.buffer)
    return server.serve()
