# ---------------------------------------------------------------- CLI
class CliError(Exception):
    def __init__(self, text):
        super().__init__(text)
        self.text = text

class HelpDisplay(Exception):
    def __init__(self, text):
        super().__init__(text)
        self.text = text

def _jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0:
        return 0.0
    match_distance = max(len1, len2) // 2 - 1
    if match_distance < 0:
        match_distance = 0
    s1_matches = [False] * len1
    s2_matches = [False] * len2
    matches = 0
    for i in range(len1):
        start = max(0, i - match_distance)
        end = min(i + match_distance + 1, len2)
        for j in range(start, end):
            if s2_matches[j] or s1[i] != s2[j]:
                continue
            s1_matches[i] = True
            s2_matches[j] = True
            matches += 1
            break
    if matches == 0:
        return 0.0
    t = 0
    k = 0
    for i in range(len1):
        if not s1_matches[i]:
            continue
        while not s2_matches[k]:
            k += 1
        if s1[i] != s2[k]:
            t += 1
        k += 1
    t //= 2
    return (matches / len1 + matches / len2 + (matches - t) / matches) / 3.0

def _best_suggestion(word, candidates):
    best = None
    best_conf = 0.0
    for cand in candidates:
        conf = _jaro(word, cand)
        if conf > 0.7 and (best is None or conf > best_conf):
            best = cand
            best_conf = conf
    return best

def _all_suggestions(word, candidates):
    scored = []
    for cand in candidates:
        conf = _jaro(word, cand)
        if conf > 0.7:
            scored.append((conf, cand))
    scored.sort(key=lambda x: x[0])
    return [c for _, c in scored]

class OptSpec:
    __slots__ = ("long", "short", "kind", "display", "dup_display")
