class ParseCtx:
    def __init__(self, name, prog):
        self.name = name
        self.prog = prog
        self.info = CTX_INFO[name]
        self.used = []  # OptSpec in encounter order (unique)
        self.seen = {}
        self.positional_value = None
        self.quiet_count = 0
    def full_usage(self):
        prog = self.prog
        n = self.name
        if n == "root":
            return f"{prog} [OPTIONS] [COMMAND]"
        if n == "check":
            return f"{prog} check [OPTIONS] [path]"
        if n == "clean":
            return f"{prog} clean"
        if n == "toolchain":
            return f"{prog} toolchain [COMMAND]"
        if n == "install":
            return f"{prog} toolchain install [OPTIONS]"
        if n == "uninstall":
            return f"{prog} toolchain uninstall"
        if n == "completions":
            return f"{prog} completions <SHELL>"
        return prog
    def smart_usage(self, involved=None):
        used = list(self.used)
        if involved is not None and involved not in used:
            used.append(involved)
        has_positional = self.positional_value is not None
        if not used and not has_positional:
            return self.full_usage()
        parts = []
        prefix = " ".join([self.prog] + self.info["path"])
        for opt in used:
            parts.append(opt.display)
        pos_name = self.info["positional"]
        if pos_name is not None:
            if has_positional:
                parts.append(f"<{pos_name}>")
            else:
                if self.info["positional_optional"]:
                    parts.append(f"[{pos_name}]")
                else:
                    parts.append(f"<{pos_name}>")
        elif self.name == "completions":
            parts.append("<SHELL>")
        if parts:
            return prefix + " " + " ".join(parts)
        return prefix

def _error_text(message, tip=None, usage=None, for_more=True):
    text = f"error: {message}\n"
    if tip is not None:
        text += f"\n  tip: {tip}\n"
    if usage is not None:
        text += f"\nUsage: {usage}\n"
    if for_more:
        text += "\nFor more information, try '--help'.\n"
    return text

def _raise_error(message, tip=None, usage=None, for_more=True):
    raise CliError(_error_text(message, tip=tip, usage=usage, for_more=for_more))

def help_text(ctx_name, prog, long_form=False):
    if ctx_name == "root":
