def _help_node_text(parent_path, prog):
    path = " ".join([prog] + parent_path + ["help"])
    return (f"Print this message or the help of the given subcommand(s)\n\nUsage: {path} [COMMAND]...\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n")

def _node_children(node_name):
