                current = "toolchain"
        elif current == "toolchain":
            current = tok  # install/uninstall
            current_path = ["toolchain", tok]
        else:
            current = tok
    if is_help_leaf:
        raise HelpDisplay(_help_node_text(help_parent_path or [], prog))
